3193|# The harness string of an engine run (reviewer.harness): agy has no --version flag (the CLI
3194|# rejects unknown flags), so the version comes from the launcher's file metadata when it
3195|# carries one: "agy-cli <version>" or "agy-cli (version unknown)". Nothing is started.
3196|function Get-EngineHarness {
3197|    param([string]$Engine, [string]$Launcher)
3198|    # (wave 23, D8) an engine that names its own version source (muse: Get-MuseHarness)
3199|    $spec = Get-EngineSpec -Name $Engine
3200|    if ($spec -and $spec.Adapter -and $spec.Adapter.PSObject.Properties['Harness'] -and $spec.Adapter.Harness) { return [string](& $spec.Adapter.Harness -Launcher $Launcher) }
3201|    $ver = ''
3202|    if ($Launcher) {
3203|        try { $ver = [string](Get-Item -LiteralPath $Launcher -ErrorAction Stop).VersionInfo.ProductVersion } catch { $ver = '' }
3204|    }
