590|# -PromptPath / -PromptText (wave 23, D1): the turn's own prompt file, written first (muse
591|# names it in its argv; its stdin is then empty). Right before the start the engine's launch
592|# invariant (D4) and the .cmd %-hazard (F02-14) are checked again: a refusal starts nothing.
593|# Reads the run's $pendingRecord, $pendingPath, $engineLauncher, $engineName and $repoRoot.
594|# { Exit (-1 unless it exited); Problem ('' or why the turn did not complete); Wall;
595|# KeepPending; Stderr (UTF-8 text); Started (a process was started: one more engine turn -
596|# for muse one more subscription prompt) }.
597|function Invoke-EngineTurn {
598|    param([string[]]$Argv, [string]$StdinText, [string]$EventsPath, [string]$StdinPath, [string]$StderrPath, [int]$Timeout, [string]$Note, [string]$PromptPath = '', [string]$PromptText = '')
599|    $t = [pscustomobject]@{ Exit = -1; Problem = ''; Wall = 0; KeepPending = $false; Stderr = ''; Started = $false }
600|    if ($PromptPath) { Write-Utf8NoBom -Path $PromptPath -Text $PromptText }
601|    Write-Utf8NoBom -Path $StdinPath -Text $StdinText
602|    $refusal = Get-EngineLaunchBlock -Engine $engineName
603|    if (-not $refusal) { $refusal = Get-CmdArgvHazard -Launcher $engineLauncher -Argv $Argv }
604|    if ($refusal) {
605|        $t.Problem = "refused before launch: $refusal"
606|        return $t
607|    }
608|    $watch = [System.Diagnostics.Stopwatch]::StartNew()
609|    $pendingRecord.state = 'launching'
610|    $pendingRecord.note = "$Note being started; its pid is not recorded yet"
611|    try { Write-PendingFile -Path $pendingPath -Record $pendingRecord } catch {
612|        $t.Problem = "could not write the recovery record ($(ConvertTo-OneLine $_.Exception.Message)); the turn was not started"
613|        return $t
614|    }
615|    $proc = $null
616|    try {
617|        $proc = Start-Process -FilePath $engineLauncher -ArgumentList ((($Argv | ForEach-Object { ConvertTo-ProcArg $_ }) -join ' ')) `
618|            -WorkingDirectory $repoRoot -NoNewWindow -PassThru `
619|            -RedirectStandardOutput $EventsPath `
620|            -RedirectStandardError $StderrPath `
621|            -RedirectStandardInput $StdinPath
622|    } catch {
623|        $t.Problem = "could not start $engineName - $(ConvertTo-OneLine $_.Exception.Message)"
624|    }
625|    if ($proc) {
