627|        $t.Started = $true
628|        $registered = $true
629|        try {
630|            $pendingRecord.state = 'running'
631|            $pendingRecord.child_pid = $proc.Id
632|            $pendingRecord.child_start_time = [string](Get-ProcessStartIso -ProcessId $proc.Id)
633|            $pendingRecord.note = $Note
