4792|        }
4793|        return $r
4794|    }
4795|    $r.Skipped = [object[]]$skipped.ToArray()
4796|    $r.Error = "no reviewer of the roster '$($Roster.Path)' is available; nothing was started: $($listing.ToArray() -join '; ') (run codex-providers.ps1 for the full picture)"
4797|    return $r
