5038|function Select-ParentThread {
5039|    param([object[]]$Consults, $Identity, [string]$Mode, [string]$Thread)
5040|    $r = [pscustomobject]@{ Mode = $Mode; Parent = ''; ParentN = $null; Note = ''; Error = '' }
5041|    $entries = @($Consults | Where-Object { $null -ne $_ })
5042|    $lineage = Format-ReviewerLineage -Provider $Identity.Provider -Model $Identity.Model -Engine ([string]$Identity.Engine)
5043|    $unresolvedMsg = "provider identity could not be resolved ($($Identity.Note)); pass -Provider and -Model explicitly, or use -Mode new"
5044|    $driftMsg = { param($t, $n, $fp) "endpoint or protocol of provider $($Identity.Provider) changed since thread $t (consult n=$n recorded provider fingerprint $(Format-ShortHash $fp), now $(Format-ShortHash $Identity.Fingerprint)); start a new thread with -Mode new" }
5045|    $thread = ([string]$Thread).Trim()
5046|    if ($thread) {
5047|        if ($Mode -eq 'new') { $r.Error = '-Thread needs -Mode fork or resume (-Mode new always starts a fresh thread).'; return $r }
5048|        if (-not $Identity.Resolved) { $r.Error = $unresolvedMsg; return $r }
5049|        $found = Find-ThreadEntry -Consults $entries -Thread $thread
5050|        if ($found.Error) { $r.Error = $found.Error; return $r }
5051|        $match = $found.Entry
5052|        $n = $found.N
5053|        $fp = Get-EntryFingerprint $match
5054|        $theirRev = Get-EntryReviewer $match
5055|        $theirs = $theirRev.Display
5056|        if (-not (Test-SameReviewer $theirRev $Identity)) {
5057|            $r.Error = "thread $thread belongs to lineage $theirs (consult n=$n); this run is $lineage. A thread never changes provider or model: use -Mode new, or run as $theirs"; return $r
5058|        }
5059|        if ($fp -ne $Identity.Fingerprint) { $r.Error = (& $driftMsg $thread $n $fp); return $r }
5060|        if (-not $r.Mode) { $r.Mode = 'fork' }
5061|        $r.Parent = $thread
5062|        $r.ParentN = $n
5063|        $r.Note = "-Thread, lineage $lineage (consult n=$n)"
5064|        return $r
5065|    }
5066|    if (-not $Identity.Resolved) {
5067|        if ($Mode -eq 'fork' -or $Mode -eq 'resume') { $r.Error = $unresolvedMsg; return $r }
5068|        $r.Mode = 'new'
5069|        $r.Note = "reviewer identity unresolved, automatic fork/resume is off ($($Identity.Note))"
5070|        return $r
5071|    }
5072|    $parent = $null
5073|    $legacy = 0; $unresolved = 0; $candidates = 0
5074|    $others = New-Object System.Collections.Generic.List[string]
5075|    for ($i = $entries.Count - 1; $i -ge 0; $i--) {
5076|        $c = $entries[$i]
5077|        $t = [string](Get-PropertyValue $c 'thread' '')
5078|        if (-not $t) {
5079|            if ([string](Get-PropertyValue $c 'thread_candidate' '')) { $candidates++ }
5080|            continue
5081|        }
5082|        if ($null -eq (Get-PropertyValue $c 'reviewer' $null)) { $legacy++; continue }
5083|        if (-not (Get-EntryFingerprint $c)) { $unresolved++; continue }
5084|        $cr = Get-EntryReviewer $c
5085|        if (-not (Test-SameReviewer $cr $Identity)) { if (-not $others.Contains($cr.Display)) { $others.Add($cr.Display) }; continue }
5086|        if (-not $parent) { $parent = $c }
5087|    }
5088|    if ($parent) {
5089|        if ($Mode -eq 'new') { return $r }
5090|        $pt = [string]$parent.thread
5091|        $n = Get-PropertyValue $parent 'n' '?'
5092|        $fp = Get-EntryFingerprint $parent
5093|        if ($fp -ne $Identity.Fingerprint) { $r.Error = (& $driftMsg $pt $n $fp); return $r }
5094|        if (-not $r.Mode) { $r.Mode = 'fork' }
5095|        $r.Parent = $pt
5096|        $r.ParentN = $n
5097|        $r.Note = "newest thread of lineage $lineage (consult n=$n)"
5098|        return $r
5099|    }
5100|    $why = New-Object System.Collections.Generic.List[string]
5101|    if ($legacy -gt 0) { $why.Add("$legacy thread(s) recorded before 0.3.0 have unknown provenance and are never automatic parents") }
5102|    if ($others.Count -gt 0) { $why.Add("other lineage(s): $($others -join ', ')") }
5103|    if ($unresolved -gt 0) { $why.Add("$unresolved thread(s) of runs with an unresolved reviewer identity are never parents") }
5104|    if ($candidates -gt 0) { $why.Add("$candidates unverified rollout candidate(s) are never parents") }
5105|    $note = "no thread of lineage $lineage in this task's ledger"
5106|    if ($why.Count -gt 0) { $note += '; ' + ($why.ToArray() -join '; ') }
5107|    if ($Mode -eq 'fork' -or $Mode -eq 'resume') {
5108|        $r.Error = "-Mode $Mode needs a parent thread: $note. Pass -Thread <uuid> of lineage $lineage, or use -Mode new"
5109|        return $r
5110|    }
5111|    $r.Mode = 'new'
5112|    if ($entries.Count -gt 0) { $r.Note = $note }
5113|    return $r
